    const pts = [];
    for (let i = 0; i <= N; i++) {
      const lon = (2 * Math.PI * i) / N, la = (lat * Math.PI) / 180;
      pts.push(toScene([r * R_EARTH * Math.cos(la) * Math.cos(lon), r * R_EARTH * Math.cos(la) * Math.sin(lon), r * R_EARTH * Math.sin(la)]));
    }
